import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { connectBlueskyHandler } from "../handlers/connectBlueskyHandler";
import type { ApiError } from "../runtime/client";
import type { ConnectBlueskyRequest } from "../types/ConnectBlueskyRequest";

type Data = Awaited<ReturnType<typeof connectBlueskyHandler>>;
type Vars = ConnectBlueskyRequest;

export function useConnectBluesky(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => connectBlueskyHandler(vars),
    ...options,
  });
}
